function tickSkinTrails(dt){const c=LEGEND_SKINS.find(c=>c.id===wallet.skin);skinTrailTick-=dt;if(c&&!reduced&&skinTrailTick<=0&&skinTrails.length<8){skinTrailTick=S.dash>0?.09:.22;const x=dogX()-39,y=GROUND+(S.y<0?S.y-48:4),g=node('g',{transform:`translate(${x},${y})`,opacity:.45});const d=c.id==='dragon'?'M-17 0Q0-9 17 0M-12 5Q0-1 12 5':c.id==='neon'?'M-19-1H9M-11 5H19':c.id==='corona'?'M-10 4L-3-15L3-5L11-19L14 4Z':'M-10-4l10-11 10 11-10 6Z';g.appendChild(node('path',{d,fill:c.id==='corona'||c.id==='eclipse'?c.fx:'none',stroke:c.fx,'stroke-width':1.5}));$('skinTrails').appendChild(g);skinTrails.push({el:g,x,y,life:.55})}skinTrails=skinTrails.filter(p=>{p.life-=dt;p.x-=110*dt;attr(p.el,'transform',`translate(${p.x},${p.y})`);attr(p.el,'opacity',Math.max(0,p.life/.55)*.38);if(p.life<=0)p.el.remove();return p.life>0})}
function legendBurst(x,y,color='#bafbe3'){if(reduced)return;if(legendBolts.length>=28)return;const g=node('g',{transform:`translate(${x},${y})`,opacity:1});g.appendChild(node('circle',{r:15,fill:'none',stroke:color,'stroke-width':3}));g.appendChild(node('path',{d:'M-30 0H30M0-30V30M-20-20L20 20M-20 20L20-20',stroke:color,'stroke-width':1.5}));$('legendBolts').appendChild(g);legendBolts.push({el:g,x,y,life:.32,total:.32,kind:'burst'})}
