function legendCollect(o){if(o.done)return;o.done=true;if(o.coin)awardCoins(voyageCoinValue());else{S.coffee++;gainEnergy();combo()}puff(o.x,o.y-25,3,o.coin?'#ffe2a4':'#c1faec')}
