function legendSuper(){if(S.mode!=='play')return;S.legendPulse=.7;if(wallet.skill==='leviathan'){for(const o of items)if(o.x>dogX()-80&&o.x<dogX()+900){if(o.coin||o.coffee)legendCollect(o);else legendBreak(o,'#affbe8')}toast('鲸落 / 今晚整条街都静音了。','#c9fff1');if(S.phase==='boss'&&B.state==='open'){shootBoss(3);S.legendSerial=B.openSerial}}else if(wallet.skill==='chrono'){S.chrono=5;S.cool=0;toast('时间拒收 / 五秒归我。','#ddd4ff');beep(310,.3,'triangle',.018)}else if(wallet.skill==='orbit'){toast('万纸归宗 / 消息全部撕碎。','#c9efff');if(S.phase==='boss'&&B.state==='open'){for(let i=0;i<3;i++)shootBoss(1)}}else if(wallet.skill==='rail')toast('雷贯穿街 / 一路不回。','#b9faff')}
