const ROUTES={story:{name:'四幕故事',duration:120},cruise:{name:'江风兜风',duration:90},contract:{name:'街头委托',duration:60},endless:{name:'凌晨循环',duration:900},dojo:{name:'拆机道场',duration:120}};
const ACHIEVEMENTS=[['first','今晚出门','完成任意亲玩路线'],['cruise','江风不催','完成一次江风兜风'],['contract','委托接住','街头委托达成至少一项目标'],['triple','全单拒收','一局街头委托达成三项目标'],['minute','熬过凌晨','凌晨循环生存60秒'],['three','野狗三更','凌晨循环生存180秒'],['dojo','练到拆机','道场击败终审官'],['story','把故事跑完','完成原版四幕亲玩故事'],['perfect','不碰审批','原版主线零受击'],['cat','七下摸狗','封面摸狗七下'],['whale','纸鲸回信','故事江边，亲手点一下纸鲸'],['secret','今晚自由','找到一处隐藏口令']];
const journeyDefaults=()=>({version:1,devClaimed:false,settings:{motion:'system'},records:{},achievements:[],secrets:[],runs:0});
let journey=journeyDefaults();
try{const old=JSON.parse(localStorage.getItem('nightOffProgressV4')||'null'),raw=old?.voyage;if(raw&&typeof raw==='object'){journey.devClaimed=raw.devClaimed===true;journey.settings.motion=['system','reduce','full'].includes(raw.settings?.motion)?raw.settings.motion:'system';journey.achievements=[...new Set((Array.isArray(raw.achievements)?raw.achievements:[]).filter(x=>ACHIEVEMENTS.some(a=>a[0]===x)))];journey.secrets=[...new Set((Array.isArray(raw.secrets)?raw.secrets:[]).filter(x=>['dog','whale','konami','0217','night'].includes(x)))];journey.runs=bounded(raw.runs,0,1000000);for(const id of ['story','cruise','contract','endless','dojo'])for(const gear of ['stock','equipped']){const k=id+':'+gear,r=raw.records?.[k];if(r&&typeof r==='object')journey.records[k]={runs:bounded(r.runs,0,1000000),best:bounded(r.best,0,10000000),time:bounded(r.time,0,900),wins:bounded(r.wins,0,1000000)}}}}catch(e){storageOK=false}
wallet.voyage=journey;
function bounded(x,a,b){return Math.max(a,Math.min(b,Math.floor(Number(x)||0)))}
const vDefaults={route:'story',life:3,finished:false,reason:'',milestone:0,shieldMark:0,elapsed:0,goals:[],daily:'',gear:'stock',resultCoins:0,recorded:false,tier:0};
const V={...vDefaults};let nextRoute='story',voyagePanel='',voyageWasPaused=false,voyageFocus=null,archivePage=0,pin='',pinMessage='',petCount=0,konamiIndex=0,settingNotice='',archiveClock=0;
function applyMotion(){reduced=journey.settings.motion==='reduce'||journey.settings.motion==='system'&&matchMedia('(prefers-reduced-motion: reduce)').matches;svg.classList.toggle('gentle',reduced)}
applyMotion();try{matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',applyMotion)}catch(e){}
function saveJourney(){wallet.voyage=journey;saveWallet()}
function dateKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function daySeed(str){let h=2166136261;for(const c of str){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function beginVoyage(mode){const route=mode==='play'&&ROUTES[nextRoute]?nextRoute:'story';nextRoute='story';Object.assign(V,vDefaults,{route,goals:[],gear:wallet.skill?'equipped':'stock'});if(route==='contract'){V.daily=dateKey();const d=daySeed(V.daily);seed=d;V.goals=[{kind:'coffee',name:'冰美式',need:6+d%3},{kind:'smashed',name:'撕碎通知',need:10+d%5},{kind:'nearMiss',name:'擦身闪避',need:2+d%2}]}else if(route==='endless')seed=daySeed('endless-v5');else if(route==='cruise')seed=71;S.safeGap=0}
function abandonVoyage(){V.finished=true;V.route='story';V.recorded=false;nextRoute='story'}
function playRoute(id){if(!ROUTES[id]||id==='story')id='story';closeVoyagePanel(false);nextRoute=id;start('play');if(id==='dojo'){S.t=120;S.bossEligible=true;S.completedMain=false;mainSnapshot={...S};startBoss();text('subtitleLine','练习不发金币 / 主线资格不受影响')}render()}
function retryVoyage(){if(voyagePanel)return;if(['boss','bossVictory','bossResult'].includes(S.phase)){startBoss();return}if(V.route!=='story'){playRoute(V.route);return}start(S.mode)}
function runDuration(){return ROUTES[V.route]?.duration||120}
function voyageCoinValue(){return V.route==='story'?1:3}
function voyageSpeed(base){if(V.route==='cruise')return 215;if(V.route==='contract')return 300;if(V.route==='endless')return 300+Math.min(240,Math.floor(S.t/30)*18);return base}
function voyageGap(base){if(V.route==='cruise')return 1.58+rnd()*.2;if(V.route==='contract')return .97+rnd()*.12;if(V.route==='endless')return Math.max(.76,1.14-Math.floor(S.t/30)*.027)+rnd()*.1;return base}
function canVoyageSpawn(){return V.route==='story'?S.t<113:V.route==='endless'?S.t<896:S.t<runDuration()-3}
function spawnVoyage(){const list=V.route==='cruise'?[['coffee',-54],['folder',0],['coffee',-145],['coin',-60],['notice',-162],['coffee',-54]]:[['coffee',-54],['folder',0],['notice',-162],['coffee',-145],['pair',0],['coffee',-54],['notice',0],['coffee',-220],['folder',0],['notice',-162],['coffee',-80]];const index=S.spawnIndex++,rotation=V.route==='contract'?daySeed(V.daily)%list.length:0;const [type,height]=list[(index+rotation)%list.length],next=list[(index+rotation+1)%list.length];const speed=voyageSpeed(300);S.safeGap=next[0]==='notice'&&next[1]<0?(type==='pair'?Math.max(1.5,530/speed):type==='folder'||type==='notice'?Math.max(1.1,430/speed):0):0;const base=mobile?930:1400;const made=items.length;if(type==='pair'){spawnOne('folder');spawnOne('notice',0,base+Math.max(165,speed*.45))}else spawnOne(type,height);if(V.route==='endless'&&S.t>=60&&index%3===1){for(const o of items.slice(made))if(!o.coin&&!o.coffee){o.armored=true;const seal=node('g');seal.appendChild(node('circle',{cy:-37,r:18,fill:'#512e3f',stroke:'#ffc4a1','stroke-width':2}));const t=node('text',{y:-31,'text-anchor':'middle','font-size':16,fill:'#ffe7c5','font-weight':800});t.textContent='章';seal.appendChild(t);o.el.appendChild(seal)}}if(index%2===0){for(let i=0;i<5;i++)spawnOne('coin',[-52,-97,-126,-97,-52][i],base+85+i*43)}}
function voyageDamage(){if(V.route==='endless')V.life=Math.max(0,V.life-1)}
function tickVoyage(dt){if(V.route==='story'||V.finished||S.phase!=='running')return;V.elapsed=S.t;V.tier=Math.floor(S.t/30);if(V.route==='endless'){const m=Math.floor(S.t/30);while(V.milestone<m){V.milestone++;awardCoins(20,'夜路里程')}const shield=Math.floor(S.t/60);if(shield>V.shieldMark){V.shieldMark=shield;S.guard=Math.min(1,S.guard+1);toast('夜路补给 / 一枚纸盾','#c7e4ff')}if(V.life===0)finishVoyage('out')}if(!V.finished&&S.t>=runDuration())finishVoyage('complete')}
function completedGoals(){return V.goals.filter(g=>S[g.kind]>=g.need).length}
function unlockJourney(id){if(journey.achievements.includes(id))return;journey.achievements.push(id);saveJourney()}
function secretFound(id){if(journey.secrets.includes(id))return false;journey.secrets.push(id);if(id==='dog')unlockJourney('cat');else if(id==='whale')unlockJourney('whale');else if(id!=='night')unlockJourney('secret');saveJourney();return true}
function recordRoute(won=false){if(V.recorded||S.mode!=='play')return;V.recorded=true;journey.runs++;const key=V.route+':'+V.gear,old=journey.records[key]||{runs:0,best:0,time:0,wins:0};old.runs++;old.best=Math.max(old.best,voyageScore());old.time=Math.max(old.time,Math.min(900,V.route==='dojo'?B.t:S.t));old.wins+=won?1:0;journey.records[key]=old;unlockJourney('first');if(V.route==='story'){unlockJourney('story');if(S.hits===0)unlockJourney('perfect')}if(V.route==='cruise'&&S.t>=90)unlockJourney('cruise');if(V.route==='contract'){if(completedGoals()>0)unlockJourney('contract');if(completedGoals()===3)unlockJourney('triple')}if(V.route==='endless'){if(S.t>=60)unlockJourney('minute');if(S.t>=180)unlockJourney('three')}if(V.route==='dojo'&&won)unlockJourney('dojo');saveJourney()}
function recordStory(){if(V.route==='story')recordRoute(S.bossWon)}
function voyageScore(){return V.route==='endless'?Math.floor(S.t)*10+score():V.route==='dojo'?S.bossWon?1000+Math.max(0,300-Math.floor(B.t)):B.landed*30:score()}
function finishVoyage(reason='complete'){if(V.finished||V.route==='story')return;if(V.route==='dojo'&&reason!=='victory'&&S.phase==='bossResult')reason='practice';if(V.route==='cruise'&&reason==='complete')awardCoins(40,'江风收工');if(V.route==='contract'&&reason==='complete')awardCoins(60+25*completedGoals(),'委托结算');V.resultCoins=S.runCoins;V.reason=reason;V.elapsed=V.route==='dojo'?B.t:S.t;recordRoute(reason==='victory');V.finished=true;clearWorld();for(const o of shots)o.el.remove();shots=[];$('bossShots').replaceChildren();S.phase='ending';S.paused=false;S.dash=0;S.freedom=0;S.chrono=0;S.y=0;S.offset=0;svg.classList.remove('paused');for(const id of['hud','skillHud','subtitle','revealCaption','freedomBanner','perfectBadge','bossHud','bossCallout','bossGate','bossResult','bossWorld'])show(id,false);show('ending',true);S.ending=V.route==='cruise'?'江风不催人':V.route==='contract'?completedGoals()===3?'三单齐收，今晚自由':'委托收工，不用加班':V.route==='endless'?reason==='out'?'耐心用完，夜路还在':'凌晨循环，自愿收工':reason==='victory'?'练熟了，拆机就行':'道场收工，主线不动';text('endTitle',S.ending);text('endLine',V.route==='cruise'?'慢慢跑。没有谁在后面打卡。':V.route==='contract'?V.goals.map(g=>`${g.name} ${Math.min(S[g.kind],g.need)} / ${g.need}`).join(' · '):V.route==='endless'?`生存 ${Math.floor(V.elapsed)} 秒 / 强度 ${V.tier+1} / 原装与装备分榜`:'三阶段练习 / 不发金币，不刷主线徽章');text('endStats',`咖啡 ${S.coffee} / 撞飞 ${S.smashed} / 擦身 ${S.nearMiss} / 连击 ${S.maxCombo}`);text('bestText',`夜航分 ${voyageScore()} · ${V.gear==='stock'?'原装榜':'装备榜'} · 本局 +${S.runCoins} 币`);text('badgeText',`夜航成就 ${journey.achievements.length} / ${ACHIEVEMENTS.length} · 档案里可查看`);text('ticketHint','夜航票根仅在本机生成');beep(760,.2);render()}
function voyageSnapshot(){return {...V,goals:V.goals.map(g=>({...g,current:S[g.kind]})),panel:voyagePanel,devClaimed:journey.devClaimed,motion:journey.settings.motion,reduced,achievements:[...journey.achievements],secrets:[...journey.secrets],records:JSON.parse(JSON.stringify(journey.records)),runs:journey.runs,pinLength:pin.length}}
function openVoyagePanel(which){if(shopOpen)toggleShop(false);if(!voyagePanel){voyageWasPaused=S.paused;voyageFocus=document.activeElement;if(['running','boss','bossVictory'].includes(S.phase))pause(true)}voyagePanel=which;for(const id of ['voyageMenu','voyageArchive','voyageDev','voyageSettings'])show(id,id==={menu:'voyageMenu',archive:'voyageArchive',dev:'voyageDev',settings:'voyageSettings'}[which]);show('voyageOverlay',true);pin='';pinMessage='';settingNotice='';if(which==='archive'){archivePage=0;if(new Date().getHours()<5&&secretFound('night'))settingNotice='02:17 / 我不是没想过。只是白天懒得说。'}voyageLayout();renderVoyagePanel();panelButtons()[0]?.focus()}
