function panelButtons(){const root=$({menu:'voyageMenu',archive:'voyageArchive',dev:'voyageDev',settings:'voyageSettings'}[voyagePanel]||'voyageMenu');return Array.from(root.querySelectorAll('.button')).filter(e=>!e.closest('.hide'))}
function devKey(k){if(voyagePanel!=='dev')return;if(k==='back')pin=pin.slice(0,-1);else if(k==='clear')pin='';else if(/^\d$/.test(k)&&pin.length<6)pin+=k;pinMessage='';renderVoyagePanel()}
function redeemDev(){if(voyagePanel!=='dev')return;if(pin==='0217'){secretFound('0217');pinMessage='凌晨 02:17 / 无米也能兜风。';pin='';renderVoyagePanel();return}if(pin!=='546603'){pinMessage='口令不对 / 没有改动金币';pin='';renderVoyagePanel();return}if(journey.devClaimed){pinMessage='本浏览器已领取 / 不重复发米';pin='';renderVoyagePanel();return}try{const live=JSON.parse(localStorage.getItem('nightOffProgressV4')||'null');if(live?.voyage?.devClaimed===true){journey.devClaimed=true;wallet.balance=bounded(live.balance,0,1000000000);pinMessage='同存档已在另一页领取 / 不重复发米';pin='';renderVoyagePanel();render();return}}catch(e){storageOK=false}const before=wallet.balance;journey.devClaimed=true;wallet.balance=Math.min(1000000000,wallet.balance+100000);saveJourney();pinMessage=`解锁成功 / 金币 +${fmt(wallet.balance-before)}${storageOK?' · 已保存':' · 存储受限，仅本页有效'}`;pin='';render();renderVoyagePanel()}
