function renderVoyagePanel(){if(!voyagePanel)return;text('voyageBalance','金币 '+fmt(wallet.balance));text('voyageStorage',storageOK?'离线单文件 / 同一浏览器同一主入口保存':'存储受限 / 当前能玩，关页可能不保留');if(voyagePanel==='menu'){text('menuContract','60秒 / 今日固定路线与目标 / 基础60 + 每单25币');text('menuEndless','3格耐心 / 强度逐步增加 / 每30秒20币');text('menuEquip','本局 '+(wallet.skill?CATALOG.skills.find(c=>c.id===wallet.skill)?.name:'原装无技能')+' / 回封面商店换装')}if(voyagePanel==='dev'){text('devPin',pin?'● '.repeat(pin.length):'输入六位口令');text('devStatus',pinMessage|| (journey.devClaimed?'已领取 100,000 金币 / 同存档仅一次':'密码解锁 +100,000 金币 / 不影响本局成绩'));text('devNote','离线彩蛋口令，不是安全锁 / 清存档会重置标记');text('devClaimText',journey.devClaimed?'核验口令':'解锁领米')}if(voyagePanel==='settings'){text('motionChoice','动画 / '+({system:'跟随系统',reduce:'减少动画',full:'完整动画'}[journey.settings.motion]));text('settingMessage',settingNotice||'减少动画不削弱技能 / 当前 '+(reduced?'减少':'完整'));text('settingSound',sound?'音效：开（主界面可切换）':'音效默认关（主界面可切换）')}if(voyagePanel==='archive'){text('archiveHead',archivePage===0?'夜航记录 / 原装与装备分榜':'夜航成就 / '+journey.achievements.length+' / '+ACHIEVEMENTS.length);const lines=[];if(archivePage===0){for(const[id,c]of Object.entries(ROUTES)){lines.push(c.name);for(const gear of ['stock','equipped']){const r=journey.records[id+':'+gear];lines.push(`  ${gear==='stock'?'原装':'装备'} · ${r?`${r.runs}局 / 最佳${r.best} / 最长${Math.floor(r.time)}秒`:'还没跑过'}`)}}}else for(const[id,name,desc]of ACHIEVEMENTS)lines.push((journey.achievements.includes(id)?'◆ ':'◇ ')+name+' / '+desc);renderLines('archiveBody',lines,mobile?20:22,mobile?46:compact?28:34);text('archiveNote',settingNotice||`完成 ${journey.runs} 局 / 彩蛋 ${journey.secrets.length} / 开发者领米不计成绩`);text('archivePageText',archivePage===0?'1 / 2':'2 / 2')}}
